379		% def:pauli-win-predicate invokes the classical game at ldparams = (q,m,d,1),
380		% whose domain (Definition def:ld-game) requires d >= 1. The hypothesis
381		% propagates to lem:pauli-completeness, thm:pauli, and cor:pauli-binary
382		% through their quantification over admissible tuples.
383		The tuple $\mathsf{qldparams} = (q,m,d)$ is \emph{admissible} if $d \ge 1$, $q$ is an admissible field size (Definition~\ref{def:admissible-size}), and $m$ divides $q$. Since an admissible field size satisfies $q \ge 2$, the divisibility forces $m \ge 1$, so an admissible tuple has all entries positive.
384	\end{definition}
