633	\section{Formalization support for finite sampling}
634	
635	The following finite-distribution identities are not named statements of the
636	source article.  They make explicit the push-forward calculations used in the
637	low-degree question and line-point laws above.
638	
639	\begin{lemma}[Extensionality of finite distributions]\label{lem:distribution-ext-support}
640		\lean{MIPStarRE.QPBT.Distribution.ext_of_support_of_weight}
641		\leanok
642		Two finite distributions with the same support and the same weight at every
643		point are equal.
644	\end{lemma}
645	\begin{proof}
646		\leanok
647		The two laws have the same finite support and assign the same mass to every
648		point, so they coincide.
649	\end{proof}
650	
651	\begin{lemma}[Composition of push-forwards]\label{lem:distribution-map-comp}
652		\lean{MIPStarRE.QPBT.Distribution.map_map}
653		\leanok
654		Let $\mu$ be a finite distribution on $A$, and let $e\colon A\to B$ and
655		$f\colon B\to C$. Then
656		\[
657			f_\ast(e_\ast\mu)=(f\circ e)_\ast\mu.
658		\]
659	\end{lemma}
660	\begin{proof}
661		\leanok
662		\uses{lem:distribution-ext-support}
663		The supports agree by composition of finite images.  For each $c\in C$,
664		partition the fiber of $f\circ e$ over $c$ by the intermediate value $e(a)$;
665		the corresponding sums of weights agree.
666	\end{proof}
667	
668	\begin{lemma}[Weights of the uniform law]\label{lem:uniform-distribution-weight}
669		\lean{MIPStarRE.QPBT.uniformDistribution_weight_apply}
670		\leanok
671		If $A$ is a nonempty finite set, then its uniform distribution assigns weight
672		$1/|A|$ to every $a\in A$.
673	\end{lemma}
674	\begin{proof}
675		\leanok
676		This is the defining weight of the uniform distribution on a nonempty finite
677		set.
678	\end{proof}
679	
680	\begin{lemma}[Uniform push-forward along a balanced map]\label{lem:uniform-map-equal-fibers}
681		\lean{MIPStarRE.QPBT.uniformDistribution_map_of_card_fiber}
682		\leanok
683		Let $A$ and $B$ be nonempty finite sets and let $e\colon A\to B$. If there is
684		an integer $c$ such that $|e^{-1}(b)|=c$ for every $b\in B$, then
685		$e_\ast\operatorname{Unif}(A)=\operatorname{Unif}(B)$.
686	\end{lemma}
687	\begin{proof}
688		\leanok
689		\uses{lem:distribution-ext-support, lem:uniform-distribution-weight}
690		Every fiber is nonempty, so $e$ is surjective and both supports are $B$.
691		Counting the fibers gives $|A|=c|B|$; summing the weight $1/|A|$ over a
692		$c$-element fiber gives $1/|B|$.
693	\end{proof}
694	
695	\begin{lemma}[Uniformity under an equivalence]\label{lem:uniform-map-equivalence}
696		\lean{MIPStarRE.QPBT.uniformDistribution_map_equiv}
697		\leanok
698		An equivalence $E\colon A\simeq B$ between nonempty finite sets satisfies
699		$E_\ast\operatorname{Unif}(A)=\operatorname{Unif}(B)$.
700	\end{lemma}
701	\begin{proof}
702		\leanok
703		\uses{lem:uniform-map-equal-fibers}
704		Every fiber of an equivalence has cardinality one, so the result follows from
705		Lemma~\ref{lem:uniform-map-equal-fibers}.
706	\end{proof}
707	
708	\begin{lemma}[First marginal of a uniform product]\label{lem:uniform-product-first-marginal}
709		\lean{MIPStarRE.QPBT.uniformDistribution_map_fst}
710		\leanok
711		For nonempty finite sets $A$ and $B$, the first marginal of
712		$\operatorname{Unif}(A\times B)$ is $\operatorname{Unif}(A)$.
713	\end{lemma}
714	\begin{proof}
715		\leanok
716		\uses{lem:uniform-map-equal-fibers}
717		Every fiber of the first projection has cardinality $|B|$; apply
718		Lemma~\ref{lem:uniform-map-equal-fibers}.
719	\end{proof}
720	
721	\begin{lemma}[Second marginal of a uniform product]\label{lem:uniform-product-second-marginal}
722		\lean{MIPStarRE.QPBT.uniformDistribution_map_snd}
723		\leanok
724		For nonempty finite sets $A$ and $B$, the second marginal of
725		$\operatorname{Unif}(A\times B)$ is $\operatorname{Unif}(B)$.
726	\end{lemma}
727	\begin{proof}
728		\leanok
729		\uses{lem:uniform-map-equal-fibers}
730		Every fiber of the second projection has cardinality $|A|$; apply
731		Lemma~\ref{lem:uniform-map-equal-fibers}.
732	\end{proof}
733	
734	\begin{lemma}[Dependent uniform sampling as a product push-forward]\label{lem:uniform-bind-map}
735		\lean{MIPStarRE.QPBT.bind_uniformDistribution_map}
736		\leanok
737		Let $A$ and $B$ be nonempty finite sets and let $g\colon A\to B\to C$.
738		Sampling $a$ uniformly from $A$, then $b$ uniformly from $B$, and returning
739		$g(a,b)$ has the same law as pushing $\operatorname{Unif}(A\times B)$ forward
740		along $(a,b)\mapsto g(a,b)$.
741	\end{lemma}
742	\begin{proof}
743		\leanok
744		\uses{lem:distribution-ext-support, lem:uniform-distribution-weight}
745		Both supports are the image of $A\times B$ under $g$.  At each $c\in C$,
746		both weights are the number of pairs $(a,b)$ with $g(a,b)=c$, divided by
747		$|A||B|$.
748	\end{proof}
